from rules import dependencies


def solve(data):
    packages = data['packages']
    names = sorted(packages)
    required = {}

    for name, bounds in data['roots'].items():
        if name not in packages:
            return {'error': 'unsatisfiable'}
        required.setdefault(name, []).append(tuple(bounds))

    best = None
    best_vector = None

    def allowed(version, constraints):
        return all((low is None or version >= low) and
                   (high is None or version <= high)
                   for low, high in constraints)

    def search(constraints, assigned):
        nonlocal best, best_vector

        for name, version in assigned.items():
            if not allowed(version, constraints[name]):
                return

        pending = [name for name in constraints if name not in assigned]
        if not pending:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best = assigned.copy()
                best_vector = vector
            return

        name = min(pending)
        for row in sorted(packages[name],
                          key=lambda item: item['version'], reverse=True):
            version = row['version']
            if not allowed(version, constraints[name]):
                continue

            next_constraints = {
                key: value.copy() for key, value in constraints.items()
            }
            next_assigned = assigned.copy()
            next_assigned[name] = version
            valid = True

            for dep_name, dep_bounds in dependencies(row.get('deps', [])):
                if dep_name not in packages:
                    valid = False
                    break
                next_constraints.setdefault(dep_name, []).append(dep_bounds)
                if (dep_name in next_assigned and
                        not allowed(next_assigned[dep_name],
                                    next_constraints[dep_name])):
                    valid = False
                    break

            if valid:
                search(next_constraints, next_assigned)

    search(required, {})
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}

def _bounds(value):
    if isinstance(value, (list, tuple)) and len(value) == 2:
        return tuple(value)
    if isinstance(value, int):
        return (value, value)
    return (None, None)


def _dependency(item):
    if isinstance(item, str):
        return item, (None, None)
    if isinstance(item, dict):
        name = item.get('name', item.get('package'))
        if name is not None:
            if 'range' in item:
                bounds = _bounds(item['range'])
            elif 'version' in item:
                bounds = _bounds(item['version'])
            elif 'min' in item or 'max' in item:
                bounds = (item.get('min'), item.get('max'))
            else:
                bounds = (None, None)
            return name, bounds
        if len(item) == 1:
            name, value = next(iter(item.items()))
            return name, _bounds(value)
    if isinstance(item, (list, tuple)) and item:
        name = item[0]
        if len(item) == 2:
            return name, _bounds(item[1])
        if len(item) >= 3:
            return name, (item[1], item[2])
    raise ValueError('invalid dependency')


def dependencies(items):
    for item in items:
        yield _dependency(item)

from rules import resolve


def solve(data):
    return resolve(
        data["packages"],
        data["roots"],
        data.get("blocked", {}),
        data.get("pins", {}),
        data.get("features", []),
    )

def resolve(packages, roots, blocked=None, pins=None, features=None):
    if not isinstance(packages, dict) or not isinstance(roots, dict):
        return {"error": "unsatisfiable"}

    blocked = blocked if isinstance(blocked, dict) else {}
    pins = pins if isinstance(pins, dict) else {}
    if not isinstance(features, (list, tuple, set, frozenset)):
        features = []
    names = sorted(packages)
    best_vector = None
    best_versions = None

    def parse_dependency(dep):
        if isinstance(dep, str):
            return dep, None, None
        if not isinstance(dep, dict):
            return None
        feature = dep.get("feature")
        if feature and feature not in features:
            return False
        name = dep.get("name")
        low = dep.get("min")
        high = dep.get("max")
        if not isinstance(name, str):
            return None
        if not isinstance(low, int) or not isinstance(high, int) or low > high:
            return None
        return name, low, high

    def in_range(version, bounds):
        low, high = bounds
        return (low is None or version >= low) and (high is None or version <= high)

    def merge_bounds(old, new):
        old_low, old_high = old
        new_low, new_high = new
        low = old_low
        if new_low is not None and (low is None or new_low > low):
            low = new_low
        high = old_high
        if new_high is not None and (high is None or new_high < high):
            high = new_high
        if low is not None and high is not None and low > high:
            return None
        return low, high

    initial_bounds = {}
    for name, interval in roots.items():
        if not isinstance(interval, (list, tuple)) or len(interval) != 2:
            return {"error": "unsatisfiable"}
        low, high = interval
        if not isinstance(low, int) or not isinstance(high, int) or low > high:
            return {"error": "unsatisfiable"}
        initial_bounds[name] = (low, high)

    # Pins constrain a package if it is selected, but do not add it to the
    # set of packages that must be installed.
    for name, version in pins.items():
        if not isinstance(version, int):
            return {"error": "unsatisfiable"}
        merged = merge_bounds(
            initial_bounds.get(name, (None, None)),
            (version, version),
        )
        if merged is None:
            return {"error": "unsatisfiable"}
        initial_bounds[name] = merged

    def rows_for(name):
        rows = packages.get(name, [])
        return rows if isinstance(rows, list) else []

    def is_blocked(name, version):
        forbidden = blocked.get(name, [])
        if not isinstance(forbidden, (list, tuple, set, frozenset)):
            return False
        return version in forbidden

    def is_acyclic(assigned):
        graph = {name: [] for name in assigned}
        for name, row in assigned.items():
            deps = row.get("deps", [])
            if not isinstance(deps, list):
                return False
            for dep in deps:
                parsed = parse_dependency(dep)
                if parsed is False:
                    continue
                if parsed is None:
                    return False
                graph[name].append(parsed[0])

        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph[name]:
                if dependency not in graph or not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def upper_bound(assigned):
        bound = []
        for name in names:
            if name in assigned:
                bound.append(assigned[name]["version"])
            else:
                versions = [
                    row["version"] for row in rows_for(name)
                    if isinstance(row, dict)
                    and isinstance(row.get("version"), int)
                    and not is_blocked(name, row["version"])
                ]
                bound.append(max([-1] + versions))
        return tuple(bound)

    def search(assigned, needed, bounds):
        nonlocal best_vector, best_versions

        if best_vector is not None and upper_bound(assigned) <= best_vector:
            return

        unresolved = sorted(needed - assigned.keys())
        if not unresolved:
            if not is_acyclic(assigned):
                return
            vector = tuple(
                assigned[name]["version"] if name in assigned else -1
                for name in names
            )
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {
                    name: assigned[name]["version"] for name in assigned
                }
            return

        name = unresolved[0]
        if name not in packages:
            return

        low, high = bounds.get(name, (None, None))
        rows = [
            row for row in rows_for(name)
            if isinstance(row, dict)
            and isinstance(row.get("version"), int)
            and in_range(row["version"], (low, high))
            and not is_blocked(name, row["version"])
        ]
        rows.sort(key=lambda row: row["version"], reverse=True)

        for row in rows:
            deps = row.get("deps", [])
            if not isinstance(deps, list):
                continue
            parsed = [parse_dependency(dep) for dep in deps]
            if any(dep is None for dep in parsed):
                continue
            parsed = [dep for dep in parsed if dep is not False]

            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_needed = set(needed)
            next_bounds = dict(bounds)
            valid = True

            for dep_name, dep_low, dep_high in parsed:
                next_needed.add(dep_name)
                merged = merge_bounds(
                    next_bounds.get(dep_name, (None, None)),
                    (dep_low, dep_high),
                )
                if merged is None:
                    valid = False
                    break
                next_bounds[dep_name] = merged
                if dep_name in next_assigned and not in_range(
                    next_assigned[dep_name]["version"], merged
                ):
                    valid = False
                    break

            if valid:
                search(next_assigned, next_needed, next_bounds)

    search({}, set(roots), initial_bounds)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

from rules import acyclic, dependency_spec, valid_interval, valid_row


def solve(data):
    if not isinstance(data, dict):
        return {"error": "unsatisfiable"}

    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = data.get("features", [])

    if not isinstance(packages, dict) or not isinstance(roots, dict):
        return {"error": "unsatisfiable"}
    if not isinstance(blocked, dict) or not isinstance(pins, dict):
        return {"error": "unsatisfiable"}
    if not isinstance(features, list) or any(not isinstance(f, str) for f in features):
        return {"error": "unsatisfiable"}
    if any(not isinstance(name, str) for name in packages) or any(
        not isinstance(name, str) for name in roots
    ):
        return {"error": "unsatisfiable"}
    if any(
        not isinstance(name, str)
        or not isinstance(versions, list)
        or any(type(version) is not int for version in versions)
        for name, versions in blocked.items()
    ):
        return {"error": "unsatisfiable"}
    if any(
        not isinstance(name, str) or type(version) is not int
        for name, version in pins.items()
    ):
        return {"error": "unsatisfiable"}

    names = sorted(packages)
    initial_bounds = {}
    for name, interval in roots.items():
        if not valid_interval(interval):
            return {"error": "unsatisfiable"}
        initial_bounds[name] = tuple(interval)

    best_vector = None
    best_versions = None

    def search(selected, required, bounds, graph):
        nonlocal best_vector, best_versions
        pending = sorted(required - selected.keys())
        if not pending:
            if not acyclic(graph):
                return
            versions = {name: row["version"] for name, row in selected.items()}
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = pending[0]
        rows = packages.get(name)
        if not isinstance(rows, list):
            return
        low, high = bounds[name]
        forbidden = set(blocked.get(name, []))

        options = sorted(
            (row for row in rows if valid_row(row)),
            key=lambda row: row["version"],
            reverse=True,
        )
        for row in options:
            version = row["version"]
            if version < low or version > high or version in forbidden:
                continue
            if name in pins and version != pins[name]:
                continue

            dependencies = []
            valid = True
            for dep in row["deps"]:
                if isinstance(dep, dict):
                    feature = dep.get("feature")
                    if feature is not None and feature != "":
                        if not isinstance(feature, str):
                            valid = False
                            break
                        if feature not in features:
                            continue
                spec = dependency_spec(dep)
                if spec is None:
                    valid = False
                    break
                dependencies.append(spec)
            if not valid:
                continue

            next_selected = dict(selected)
            next_selected[name] = row
            next_required = set(required)
            next_bounds = dict(bounds)
            next_graph = dict(graph)
            next_graph[name] = [dep_name for dep_name, _, _ in dependencies]
            feasible = True

            for dep_name, dep_low, dep_high in dependencies:
                next_required.add(dep_name)
                if dep_name in next_bounds:
                    old_low, old_high = next_bounds[dep_name]
                    dep_low = max(old_low, dep_low)
                    dep_high = min(old_high, dep_high)
                if dep_low > dep_high:
                    feasible = False
                    break
                next_bounds[dep_name] = (dep_low, dep_high)

                if dep_name in next_selected:
                    dep_version = next_selected[dep_name]["version"]
                    if dep_version < dep_low or dep_version > dep_high:
                        feasible = False
                        break

            if feasible:
                search(next_selected, next_required, next_bounds, next_graph)

    search({}, set(roots), initial_bounds, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

def valid_row(row):
    return (
        isinstance(row, dict)
        and type(row.get("version")) is int
        and isinstance(row.get("deps"), list)
    )


def valid_interval(interval):
    return (
        isinstance(interval, (list, tuple))
        and len(interval) == 2
        and type(interval[0]) is int
        and type(interval[1]) is int
        and interval[0] <= interval[1]
    )


def dependency_spec(dep):
    if not isinstance(dep, dict):
        return None
    name = dep.get("name")
    low = dep.get("min")
    high = dep.get("max")
    if not isinstance(name, str) or type(low) is not int or type(high) is not int:
        return None
    if low > high:
        return None
    return name, low, high


def acyclic(graph):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for dependency in graph.get(name, []):
            if not visit(dependency):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in graph)

from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    initial_requirements = {}
    for name, bounds in roots.items():
        initial_requirements.setdefault(name, []).append(tuple(bounds))

    def active_dependencies(row):
        for dep in row.get("deps", []):
            feature = dep.get("feature")
            if feature and feature not in features:
                continue
            yield dep

    def is_acyclic(versions, assigned):
        graph = {name: [] for name in versions}
        for name in versions:
            row = assigned[name]
            for dep in active_dependencies(row):
                target = dep["name"]
                if target not in versions:
                    return False
                graph[name].append(target)
        visiting = set()
        visited = set()

        def visit(node):
            if node in visiting:
                return False
            if node in visited:
                return True
            visiting.add(node)
            for target in graph[node]:
                if not visit(target):
                    return False
            visiting.remove(node)
            visited.add(node)
            return True

        return all(visit(node) for node in graph)

    def search(assigned, requirements, expanded):
        nonlocal best_vector, best_versions
        requirements = {name: list(ranges) for name, ranges in requirements.items()}
        expanded = set(expanded)

        # Expand dependency constraints for every selected version.
        changed = True
        while changed:
            changed = False
            for name, row in list(assigned.items()):
                if name in expanded:
                    continue
                expanded.add(name)
                changed = True
                for dep in active_dependencies(row):
                    requirements.setdefault(dep["name"], []).append(
                        (dep["min"], dep["max"])
                    )

        for name, row in assigned.items():
            version = row["version"]
            if any(not lo <= version <= hi for lo, hi in requirements.get(name, [])):
                return
            if version in blocked.get(name, []):
                return
            if name in pins and version != pins[name]:
                return

        domains = {}
        for name in requirements:
            if name in assigned:
                continue
            candidates = []
            for row in packages.get(name, []):
                version = row["version"]
                if any(not lo <= version <= hi for lo, hi in requirements[name]):
                    continue
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                candidates.append(row)
            if not candidates:
                return
            domains[name] = candidates

        # An admissible lexicographic upper bound lets us discard inferior branches.
        if best_vector is not None:
            upper = []
            for name in names:
                if name in assigned:
                    upper.append(assigned[name]["version"])
                elif name in domains:
                    upper.append(max(row["version"] for row in domains[name]))
                else:
                    rows = packages.get(name, [])
                    upper.append(max((row["version"] for row in rows), default=-1))
            if tuple(upper) <= best_vector:
                return

        if not domains:
            versions = {name: row["version"] for name, row in assigned.items()}
            if not is_acyclic(versions, assigned):
                return
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = min(domains, key=lambda n: (len(domains[n]), n))
        for row in sorted(domains[name], key=lambda r: r["version"], reverse=True):
            next_assigned = dict(assigned)
            next_assigned[name] = row
            search(next_assigned, requirements, expanded)

    search({}, initial_requirements, set())
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    latest = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        event_id = event.get('id')
        key = ('id', event_id) if 'id' in event else ('anonymous', position)
        revision = event.get('revision', 0)
        if key not in latest or revision >= latest[key][0]:
            latest[key] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in latest.values():
        if event.get('void') is True:
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances.setdefault(key, 0)
        balances[key] += amount(event, data['rounding'])

    return {'balances': balances}

def _rounded_ratio(value, mode):
    if mode == 'floor':
        return value // 10000
    if mode == 'half_up':
        return (value + 5000) // 10000
    raise ValueError(f"Unsupported rounding mode: {mode}")


def amount(e, mode):
    base = e['price'] * e.get('quantity', 1)
    discount_bp = max(0, min(10000, e.get('discount_bp', 0)))
    net = _rounded_ratio(base * (10000 - discount_bp), mode)
    tax = _rounded_ratio(net * e.get('tax_bp', 0), mode)
    total = net + tax
    if e.get('kind') == 'refund':
        total = -total
    return total

from rules import active_deps, is_acyclic


def solve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)

    best_score = None
    best_versions = None

    def domain(name, constraints):
        if name not in packages:
            return []
        forbidden = set(blocked.get(name, []))
        pin = pins.get(name)
        result = []
        for row in packages[name]:
            version = row["version"]
            if version in forbidden or (pin is not None and version != pin):
                continue
            if all(low <= version <= high for low, high in constraints.get(name, [])):
                result.append(row)
        return result

    def upper_bound(assigned, constraints):
        bound = []
        for name in names:
            if name in assigned:
                bound.append(assigned[name]["version"])
            elif name in constraints:
                rows = domain(name, constraints)
                if not rows:
                    return None
                bound.append(max(row["version"] for row in rows))
            else:
                rows = domain(name, {})
                bound.append(max([-1] + [row["version"] for row in rows]))
        return tuple(bound)

    def visit(assigned, constraints):
        nonlocal best_score, best_versions

        bound = upper_bound(assigned, constraints)
        if bound is None or (best_score is not None and bound <= best_score):
            return

        pending = [name for name in constraints if name not in assigned]
        if not pending:
            if not is_acyclic(assigned, features):
                return
            score = tuple(assigned[name]["version"] if name in assigned else -1 for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {name: assigned[name]["version"] for name in assigned}
            return

        choices = []
        for name in pending:
            rows = domain(name, constraints)
            if not rows:
                return
            choices.append((len(rows), name, rows))
        _, name, rows = min(choices, key=lambda item: (item[0], item[1]))
        rows = sorted(rows, key=lambda row: row["version"], reverse=True)

        for row in rows:
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_constraints = {key: list(value) for key, value in constraints.items()}
            valid = True
            for dep in active_deps(row, features):
                dep_name = dep["name"]
                next_constraints.setdefault(dep_name, []).append((dep["min"], dep["max"]))
                if dep_name in next_assigned:
                    version = next_assigned[dep_name]["version"]
                    if not all(low <= version <= high for low, high in next_constraints[dep_name]):
                        valid = False
                        break
            if valid:
                visit(next_assigned, next_constraints)

    initial_constraints = {name: [tuple(interval)] for name, interval in roots.items()}
    visit({}, initial_constraints)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

def active_deps(row, features):
    result = []
    for dep in row.get("deps", []):
        feature = dep.get("feature")
        if feature and feature not in features:
            continue
        result.append(dep)
    return result


def is_acyclic(assigned, features):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for dep in active_deps(assigned[name], features):
            target = dep["name"]
            if target not in assigned or not visit(target):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in assigned)

from rules import choices


def _acyclic(graph):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True

        state[name] = 1
        for dependency in graph.get(name, ()):
            if dependency in graph and not visit(dependency):
                return False
        state[name] = 2
        return True

    for name in graph:
        if state.get(name, 0) == 0 and not visit(name):
            return False
    return True


def solve(data):
    packages = data['packages']
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = data.get('features', [])
    names = sorted(packages)
    best_vector = None
    best_versions = None

    initial_constraints = {
        name: [tuple(bounds)] for name, bounds in roots.items()
    }

    def search(versions, constraints, graph):
        nonlocal best_vector, best_versions

        for name, version in versions.items():
            if any(
                (low is not None and version < low)
                or (high is not None and version > high)
                for low, high in constraints.get(name, ())
            ):
                return

        pending = set(constraints) - set(versions)
        if not pending:
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(versions)
            return

        name = min(pending)
        rows = choices(
            packages.get(name, ()), constraints[name], blocked.get(name, ())
        )
        if name in pins:
            rows = [row for row in rows if row['version'] == pins[name]]

        for row in rows:
            updated_versions = dict(versions)
            updated_versions[name] = row['version']

            updated_constraints = {
                package: list(ranges)
                for package, ranges in constraints.items()
            }
            updated_graph = {
                package: list(dependencies)
                for package, dependencies in graph.items()
            }
            active_dependencies = []
            for dependency in row.get('deps', ()):
                feature = dependency.get('feature')
                if feature and feature not in features:
                    continue
