def _round_ratio(numerator, denominator, mode):
    if mode == 'floor':
        return numerator // denominator
    return (2 * numerator + denominator) // (2 * denominator)


def amount(event, mode):
    price = event['price']
    quantity = event.get('quantity', 1)
    discount = max(0, min(10000, event.get('discount_bp', 0)))

    net = _round_ratio(price * quantity * (10000 - discount), 10000, mode)
    tax_bp = event.get('tax_bp', 0)
    tax = _round_ratio(net * tax_bp, 10000, mode)
    total = net + tax

    if event.get('kind') == 'refund':
        return -total
    return total

