def _dependency(dep):
    lo = hi = None
    if isinstance(dep, str):
        return dep, lo, hi
    if isinstance(dep, dict):
        name = dep.get('name', dep.get('package'))
        if name is None and len(dep) == 1:
            name, bounds = next(iter(dep.items()))
            if isinstance(bounds, int):
                lo = hi = bounds
            elif isinstance(bounds, (list, tuple)) and len(bounds) == 2:
                lo, hi = bounds
            return name, lo, hi
        if name is None:
            raise ValueError('invalid dependency')
        bounds = dep.get('range', dep.get('versions'))
        if bounds is not None and isinstance(bounds, (list, tuple)) and len(bounds) == 2:
            lo, hi = bounds
        elif 'version' in dep:
            lo = hi = dep['version']
        else:
            lo, hi = dep.get('min'), dep.get('max')
        return name, lo, hi
    if isinstance(dep, (list, tuple)) and dep:
        name = dep[0]
        if len(dep) == 2:
            bounds = dep[1]
            if isinstance(bounds, int):
                lo = hi = bounds
            elif isinstance(bounds, (list, tuple)) and len(bounds) == 2:
                lo, hi = bounds
        elif len(dep) >= 3:
            lo, hi = dep[1], dep[2]
        return name, lo, hi
    raise ValueError('invalid dependency')


def _active(dep, features):
    if isinstance(dep, dict):
        feature = dep.get('feature')
        if feature:
            return feature in features
    return True


def _forbidden(blocked, name, version):
    values = blocked.get(name, ())
    if isinstance(values, (list, tuple, set, frozenset)):
        return version in values
    return version == values


def _acyclic(selected_rows, features):
    graph = {}
    for name, row in selected_rows.items():
        graph[name] = [
            _dependency(dep)[0]
            for dep in row.get('deps', [])
            if _active(dep, features)
        ]

    colors = {}

    def visit(name):
        color = colors.get(name, 0)
        if color == 1:
            return False
        if color == 2:
            return True
        colors[name] = 1
        for target in graph.get(name, []):
            if target in graph and not visit(target):
                return False
        colors[name] = 2
        return True

    return all(visit(name) for name in graph)


