              for name, interval in roots.items()}
    best_score = None
    best_versions = None

    def search(selected_rows, needed, current_limits):
        nonlocal best_score, best_versions
        pending = sorted(needed - selected_rows.keys())
        if not pending:
            if not _acyclic(selected_rows, features):
                return
            score = tuple(selected_rows[name]['version'] if name in selected_rows else -1
                          for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = {name: row['version']
                                 for name, row in selected_rows.items()}
            return

        name = pending[0]
