                new_lo = old_lo if dep_lo is None else dep_lo if old_lo is None else max(old_lo, dep_lo)
                new_hi = old_hi if dep_hi is None else dep_hi if old_hi is None else min(old_hi, dep_hi)
                if new_lo is not None and new_hi is not None and new_lo > new_hi:
                    valid = False
