                    chosen = next_rows[target]['version']
                    if ((new_lo is not None and chosen < new_lo)
                            or (new_hi is not None and chosen > new_hi)):
                        valid = False
                        break
            if valid:
                search(next_rows, next_needed, next_limits)

    search({}, set(roots), limits)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

