def has_cycle(graph):
    state = {}

    def visit(node):
        mark = state.get(node, 0)
        if mark == 1:
            return True
        if mark == 2:
            return False
        state[node] = 1
        for target in graph.get(node, []):
            if visit(target):
                return True
        state[node] = 2
        return False

    for node in graph:
        if visit(node):
            return True
    return False

