            return _bounds(value["range"])
        low = value.get("min", value.get("minimum", value.get("min_version")))
        high = value.get("max", value.get("maximum", value.get("max_version")))
        return (low, high)
    if isinstance(value, (list, tuple)):
        if len(value) == 2:
            return (value[0], value[1])
        if len(value) == 1:
            return (value[0], value[0])
    if type(value) is int:
        return (value, value)
    return (None, None)


