    if isinstance(dep, (list, tuple)) and dep:
        if len(dep) == 2:
            return dep[0], _bounds(dep[1])
        if len(dep) >= 3:
            return dep[0], (dep[1], dep[2])
        return dep[0], (None, None)
    if not isinstance(dep, dict):
        return None

    name = dep.get("name", dep.get("package", dep.get("pkg")))
    if name is None and len(dep) == 1:
        name, spec = next(iter(dep.items()))
        return name, _bounds(spec)
    if name is None:
