    spec = dep.get("range", dep.get("version_range", dep.get("versions")))
    if spec is None and "version" in dep:
        spec = dep["version"]
    if spec is not None:
        bounds = _bounds(spec)
    else:
        bounds = (
            dep.get("min", dep.get("min_version")),
