    pins = data.get("pins", {})
    blocked = data.get("blocked", {})
    features = data.get("features", []) or []

    constraints = {}
    for name, interval in roots.items():
        constraints.setdefault(name, []).append(_bounds(interval))

    best_key = None
    best_versions = None

    def search(assigned, required, graph):
        nonlocal best_key, best_versions

        for name, version in assigned.items():
            if not _allowed(version, required.get(name, [])):
                return
            if name in pins and version != pins[name]:
                return
            if version in blocked.get(name, []):
                return

        pending = [name for name in required if name not in assigned]
        if not pending:
            if not _acyclic(graph):
                return
            key = tuple(assigned.get(name, -1) for name in names)
            if best_key is None or key > best_key:
                best_key = key
                best_versions = dict(assigned)
            return

        name = min(pending)
        choices = [
            row for row in packages.get(name, [])
            if isinstance(row, dict)
            and type(row.get("version")) is int
            and _allowed(row["version"], required[name])
            and (name not in pins or row["version"] == pins[name])
            and row["version"] not in blocked.get(name, [])
        ]
        choices.sort(key=lambda row: row["version"], reverse=True)

        for row in choices:
            version = row["version"]
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_required = {pkg: list(bounds) for pkg, bounds in required.items()}
            next_graph = {pkg: list(deps) for pkg, deps in graph.items()}
            active_dependencies = []
            valid = True

            for dep in row.get("deps", []):
                if isinstance(dep, dict):
                    feature = dep.get("feature")
                    if feature not in (None, "") and feature not in features:
                        continue

                parsed = _dependency(dep)
                if parsed is None:
                    valid = False
                    break
                dep_name, bounds = parsed
                if not isinstance(dep_name, str):
                    valid = False
                    break

                active_dependencies.append(dep_name)
                next_required.setdefault(dep_name, []).append(bounds)
                if dep_name in next_assigned and not _allowed(
                    next_assigned[dep_name], next_required[dep_name]
                ):
                    valid = False
                    break

            if valid:
                next_graph[name] = active_dependencies
                search(next_assigned, next_required, next_graph)

    search({}, constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    latest = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            event_id = ('id', event['id'])
            revision = event.get('revision', 0)
        else:
            event_id = ('anonymous', position)
            revision = 0

        previous = latest.get(event_id)
        if previous is None or revision >= previous[0]:
            latest[event_id] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in latest.values():
        if event.get('void') is True:
            continue

        account = event.get('account') or 'default'
        currency = event.get('currency') or 'USD'
        key = f'{account}|{currency}'
        value = amount(event, data['rounding'])
        if event.get('kind') == 'refund':
            value = -value
        balances[key] = balances.get(key, 0) + value

    if not balances:
        balances['default|USD'] = 0
    return {'balances': balances}

