def solve_packages(data):
    packages = data['packages']
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    domains = {}
    for name, rows in packages.items():
        forbidden = set(blocked.get(name, []))
        domains[name] = [row for row in rows
                         if row['version'] not in forbidden]
        domains[name].sort(key=lambda row: row['version'], reverse=True)

    constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
    best_key = None
    best_versions = None

    def candidates(name, requirements):
        if name not in domains:
            return []
        pin = pins.get(name)
        return [row for row in domains[name]
                if (pin is None or row['version'] == pin)
                and all(low <= row['version'] <= high
                        for low, high in requirements)]

    def has_path(graph, start, goal):
        stack = [start]
        seen = set()
        while stack:
            node = stack.pop()
            if node == goal:
                return True
            if node not in seen:
                seen.add(node)
                stack.extend(graph.get(node, ()))
        return False

    def search(selected, requirements, graph):
        nonlocal best_key, best_versions

        pending = [name for name in requirements if name not in selected]

        if best_key is not None:
            upper = []
            for name in names:
                if name in selected:
                    upper.append(selected[name])
                elif name in requirements:
                    possible = candidates(name, requirements[name])
                    if not possible:
                        return
                    upper.append(max(row['version'] for row in possible))
                else:
                    possible = domains[name]
                    upper.append(max([-1] + [row['version'] for row in possible]))
            if tuple(upper) <= best_key:
                return

        if not pending:
            key = tuple(selected.get(name, -1) for name in names)
            if best_key is None or key > best_key:
                best_key = key
                best_versions = dict(selected)
            return

        name = min(pending)
        for row in candidates(name, requirements[name]):
            version = row['version']
            next_selected = dict(selected)
            next_selected[name] = version
            next_requirements = {key: list(value)
                                 for key, value in requirements.items()}
            next_graph = {key: list(value) for key, value in graph.items()}
            next_graph.setdefault(name, [])
            active_deps = []
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                low, high = dep['min'], dep['max']
                if target not in domains:
                    valid = False
                    break
                if target in next_selected:
                    target_version = next_selected[target]
                    if not low <= target_version <= high:
                        valid = False
                        break
                else:
                    next_requirements.setdefault(target, []).append((low, high))
                active_deps.append(target)

            if not valid:
                continue

            for target in active_deps:
                if has_path(next_graph, target, name):
                    valid = False
                    break
                next_graph[name].append(target)

            if valid:
                search(next_selected, next_requirements, next_graph)

    if any(name not in domains for name in roots):
        return {'error': 'unsatisfiable'}
    search({}, constraints, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

from rules import choose


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    bounds = {}
    required = set(roots)
    for name, interval in roots.items():
        bounds[name] = (interval[0], interval[1])

    best_score = None
    best_versions = None

    def acyclic(selected):
        graph = {name: [] for name in selected}
        for name, row in selected.items():
            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                if target not in selected:
                    return False
                graph[name].append(target)

        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for target in graph[name]:
                if not visit(target):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(selected, current_bounds, current_required):
        nonlocal best_score, best_versions

        unresolved = sorted(current_required - selected.keys())
        if not unresolved:
            if not acyclic(selected):
                return
            versions = {name: row['version'] for name, row in selected.items()}
            score = tuple(versions.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = versions
            return

        name = unresolved[0]
        if name not in packages:
            return
        low, high = current_bounds.get(name, (float('-inf'), float('inf')))
        choices = choose(packages[name])
        for row in choices:
            version = row['version']
            if version < low or version > high:
                continue
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue

            next_selected = dict(selected)
            next_selected[name] = row
            next_bounds = dict(current_bounds)
            next_required = set(current_required)
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                dep_low, dep_high = dep['min'], dep['max']
                old_low, old_high = next_bounds.get(
                    target, (float('-inf'), float('inf'))
                )
                new_low = max(old_low, dep_low)
                new_high = min(old_high, dep_high)
                if new_low > new_high or target not in packages:
                    valid = False
                    break
                next_bounds[target] = (new_low, new_high)
                next_required.add(target)
                if target in next_selected:
                    chosen_version = next_selected[target]['version']
                    if not new_low <= chosen_version <= new_high:
                        valid = False
                        break

            if valid:
                search(next_selected, next_bounds, next_required)

    search({}, bounds, required)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}

def choose(rows):
    """Return candidate rows in descending version order."""
    return sorted(rows, key=lambda row: row['version'], reverse=True)

from rules import options


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    names = sorted(packages)
    best_vector = None
    best_assignment = None

    def satisfies(version, limits):
        return all(
            (minimum is None or version >= minimum)
            and (maximum is None or version <= maximum)
            for minimum, maximum in limits
        )

    def visit(assignment, required, constraints):
        nonlocal best_vector, best_assignment

        unresolved = required.difference(assignment)
        if not unresolved:
            vector = tuple(
                assignment[name]['version'] if name in assignment else -1
                for name in names
            )
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_assignment = dict(assignment)
            return

        name = min(unresolved)
        if name not in packages:
            return

        limits = constraints.get(name, [])
        minimum = max(
            (low for low, _ in limits if low is not None), default=None
        )
        maximum = min(
            (high for _, high in limits if high is not None), default=None
        )
        bounds = (minimum, maximum) if limits else None
        forbidden = blocked.get(name, [])

        for row in options(packages[name], bounds):
            version = row['version']
            if version in forbidden:
                continue
            if name in pins and version != pins[name]:
                continue
            if not satisfies(version, limits):
                continue

            next_assignment = dict(assignment)
            next_assignment[name] = row
            next_required = set(required)
            next_constraints = {
                key: list(value) for key, value in constraints.items()
            }
            valid = True

            for dependency in row.get('deps', []):
                if isinstance(dependency, str):
                    dep_name = dependency
                    dep_limits = (None, None)
                else:
                    dep_name = dependency['name']
                    dep_limits = (
                        dependency.get('min'),
                        dependency.get('max'),
                    )

                next_required.add(dep_name)
                next_constraints.setdefault(dep_name, []).append(dep_limits)
                if dep_name in next_assignment and not satisfies(
                    next_assignment[dep_name]['version'],
                    next_constraints[dep_name],
                ):
                    valid = False
                    break

            if valid:
                visit(next_assignment, next_required, next_constraints)

    initial_constraints = {}
    for name, bounds in roots.items():
        initial_constraints.setdefault(name, []).append(tuple(bounds))

    visit({}, set(roots), initial_constraints)
    if best_assignment is None:
        return {'error': 'unsatisfiable'}

    return {
        'versions': {
            name: best_assignment[name]['version']
            for name in best_assignment
        }
    }

def options(rows, bounds=None):
    if bounds is None:
        valid = list(rows)
    else:
        minimum, maximum = bounds
        valid = [
            row for row in rows
            if (minimum is None or row['version'] >= minimum)
            and (maximum is None or row['version'] <= maximum)
        ]
    return sorted(valid, key=lambda row: row['version'], reverse=True)

from rules import allowed, acyclic


def solve(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    constraints = {}
    for name, interval in data["roots"].items():
        constraints.setdefault(name, []).append((interval[0], interval[1]))

    best_versions = None
    best_vector = None

    def candidates(name, limits):
        rows = [row for row in packages.get(name, [])
                if allowed(name, row, limits, data)]
        return sorted(rows, key=lambda row: row["version"], reverse=True)

    def search(selected, limits, edges):
        nonlocal best_versions, best_vector

        domains = {}
        for name in limits:
            if name not in selected:
                domain = candidates(name, limits[name])
                if not domain:
                    return
                domains[name] = domain

        upper = []
        for name in names:
            if name in selected:
                upper.append(selected[name]["version"])
            elif name in limits:
                upper.append(max(row["version"] for row in domains[name]))
            else:
                rows = packages.get(name, [])
                upper.append(max((row["version"] for row in rows), default=-1))
        upper = tuple(upper)
        if best_vector is not None and upper <= best_vector:
            return

        if not domains:
            vector = tuple(selected[name]["version"] if name in selected else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: selected[name]["version"] for name in selected}
            return

        name = min(domains)
        for row in domains[name]:
            next_selected = selected.copy()
            next_selected[name] = row
            next_limits = {key: value.copy() for key, value in limits.items()}
            next_edges = {key: value.copy() for key, value in edges.items()}
            next_edges.setdefault(name, set())
            valid = True

            for dep in row.get("deps", []):
                feature = dep.get("feature")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                next_limits.setdefault(target, []).append((dep["min"], dep["max"]))
                next_edges[name].add(target)
                if (target in next_selected and
                        not allowed(target, next_selected[target], next_limits[target], data)):
                    valid = False
                    break

            if valid and acyclic(next_edges):
                search(next_selected, next_limits, next_edges)

    search({}, constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}

def allowed(name, row, limits, data):
    version = row["version"]
    if any(version < low or version > high for low, high in limits):
        return False
    if version in data.get("blocked", {}).get(name, []):
        return False
    pins = data.get("pins", {})
    return name not in pins or pins[name] == version


def acyclic(edges):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for target in edges.get(name, ()):
            if not visit(target):
                return False
        state[name] = 2
        return True

    return all(visit(name) for name in edges)

from rules import amount


def solve(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}

    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue

        if "id" not in event:
            key = ("anonymous", position)
            winners[key] = (None, position, event)
            continue

        key = ("id", event["id"])
        revision = event.get("revision", 0)
        previous = winners.get(key)
        if previous is None or revision > previous[0] or (
            revision == previous[0] and position > previous[1]
        ):
            winners[key] = (revision, position, event)

    balances = {}
    for _, _, event in winners.values():
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = f"{account}|{currency}"
        balances[key] = balances.get(key, 0) + amount(event, data["rounding"])

    return {"balances": balances}

def _round(numerator, mode):
    if mode == "floor":
        return numerator // 10000
    return (numerator + 5000) // 10000


def amount(event, mode):
    gross = event["price"] * event.get("quantity", 1)
    discount_bp = max(0, min(10000, event.get("discount_bp", 0)))
    net = _round(gross * (10000 - discount_bp), mode)

    tax_bp = event.get("tax_bp", 0)
    value = net + _round(net * tax_bp, mode)

    if event.get("kind") == "refund":
        return -value
    return value

from rules import amount


def solve(data):
    events = data.get('events', [])
    cutoff = data.get('cutoff', 10**9)
    rounding = data.get('rounding', 'half_up')

    # Filter before resolving duplicates, retaining original positions for tie breaks.
    winners = {}
    for position, event in enumerate(events):
        if event.get('sequence', 0) > cutoff:
            continue
        if 'id' in event:
            key = ('id', event['id'])
        else:
            key = ('anonymous', position)
        rank = (event.get('revision', 0), position)
        if key not in winners or rank > winners[key][0]:
            winners[key] = (rank, event)

    balances = dict(data.get('opening', {}))
    for _, event in winners.values():
        if event.get('void', False):
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        balances[key] += amount(event, rounding)

    return {'balances': balances}
